const API='/api';
const BRAND_THEMES=['mors','ocean','ember','light'];
function applyTheme(value){const theme=BRAND_THEMES.includes(value)?value:'mors';document.body.dataset.theme=theme;const select=document.querySelector('#theme-select');if(select)select.value=theme;try{localStorage.setItem('mors-aegis-theme-v2',theme)}catch{}}
const navItems=[['mission','Mission Control'],['experiments','Experiment Universe'],['data','Scientific Data Explorer'],['gallery','Science Gallery'],['archive','Raw Data Vault'],['spacetime','Space-Time Explorer'],['quantum','Quantum Lab'],['combustion','Combustion Lab'],['intelligence','AI Intelligence'],['earth','Earth Fire Observatory'],['environment','Space Environment'],['twin','Digital Twin'],['safety','Safety Intelligence'],['research','Research Explorer'],['architecture','System Architecture'],['methodology','Methodology'],['about','About MORS'],['pitch','Project Brief']];
const state={experiments:[],mission:null,scienceOverview:null,scienceOverviewLoading:null,galleryDataset:'fires',galleryOffset:0,view:'mission'};
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function request(path,options={}){
  const active=document.activeElement;
  const pending=options.method&&options.method!=='GET'?(active instanceof HTMLButtonElement?active:active instanceof HTMLInputElement&&active.type==='file'?active:active?.closest('form')?.querySelector('button[type="submit"],button:not([type])')):null;
  if(pending)pending.disabled=true;
  try{
    const r=await fetch(API+path,{credentials:'same-origin',...options});
    const body=await r.json().catch(()=>({detail:'Unexpected server response'}));
    if(r.status===401)showGate();
    if(!r.ok){const detail=Array.isArray(body.detail)?body.detail.map(x=>x.msg||String(x)).join('; '):body.detail;throw new Error(typeof detail==='string'?detail:detail?.message||`Request failed (${r.status})`)}
    return body;
  }finally{if(pending)pending.disabled=false}
}
function showGate(){const gate=$('#auth-gate');$('.shell').inert=true;gate.hidden=false;$('#auth-token').focus()}
function hideGate(){$('#auth-gate').hidden=true;$('.shell').inert=false;$('#auth-token').value=''}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500)}
function heading(kicker,title,desc,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`}
function panel(title,subtitle,body,extra=''){return `<section class="panel ${extra}"><div class="panel-head"><div><h2 class="panel-title">${title}</h2>${subtitle?`<div class="panel-subtitle">${subtitle}</div>`:''}</div></div>${body}</section>`}
function banner(text,type=''){return `<div class="banner ${type}"><span class="mark">${type==='blue'?'ⓘ':'⚠'}</span><span>${text}</span></div>`}
function sourceLink(e){if(!e||!/^https:\/\/ntrs\.nasa\.gov\/citations\/[0-9]+$/.test(e.record||''))return '<span>Source link unavailable</span>';return `<a href="${esc(e.record)}" target="_blank" rel="noreferrer">NASA NTRS ↗</a>`}
function lineChart(){const grouped=new Map();for(const item of state.experiments){const year=Number(item.year);grouped.set(year,(grouped.get(year)||0)+1)}const vals=[...grouped].sort((a,b)=>a[0]-b[0]);const w=700,h=180,p=30,min=0,max=Math.max(2,...vals.map(x=>x[1]));const pts=vals.map((entry,i)=>`${vals.length===1?w/2:p+i*(w-2*p)/(vals.length-1)},${h-p-(entry[1]-min)/(max-min)*(h-2*p)}`).join(' ');const area=`${p},${h-p} ${pts} ${w-p},${h-p}`;let grid='';for(let i=0;i<4;i++){const y=p+i*(h-2*p)/3;grid+=`<line x1="${p}" y1="${y}" x2="${w-p}" y2="${y}" class="chart-grid"/><text x="0" y="${y+3}" class="chart-axis">${Math.round(max*(1-i/3))}</text>`}return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Illustrative timeline of catalogued NASA records, not fire intensity or experimental measurements"><defs><linearGradient id="areaFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#53d3e2" stop-opacity=".21"/><stop offset="1" stop-color="#53d3e2" stop-opacity="0"/></linearGradient></defs>${grid}<polygon points="${area}" class="chart-area"/><polyline points="${pts}" class="chart-line"/>${vals.map((entry,i)=>`<text x="${vals.length===1?w/2:p+i*(w-2*p)/(vals.length-1)}" y="${h-2}" text-anchor="middle" class="chart-axis">${entry[0]}</text><circle class="chart-point" data-point="${i}" tabindex="0" role="button" aria-label="${entry[0]}: ${entry[1]} indexed records" cx="${vals.length===1?w/2:p+i*(w-2*p)/(vals.length-1)}" cy="${h-p-(entry[1]-min)/(max-min)*(h-2*p)}" r="5" fill="#53d3e2"><title>${entry[0]} · ${entry[1]} local catalog records</title></circle>`).join('')}</svg>`}
function committeeView(){return `${heading('MORS AEGIS · BRIEFING FOR REVIEWERS','A research platform for space fire safety','Bring available evidence into one inspectable workflow, keeping measurements, analysis, and hypotheses distinct.','<a class="button secondary" href="/files/MORS_AEGIS_Committee_Brief_AR.pptx" download>Download Arabic committee presentation (PPTX)</a>')}
<section class="committee-hero panel"><span class="kicker">THE IDEA IN ONE SENTENCE</span><h2>Turn scattered scientific sources into answers whose evidence can be traced.</h2><p>MORS AEGIS helps researchers find microgravity combustion records, inspect Earth-observation detections from FIRMS, and check what the available data can support before interpreting it.</p><div class="committee-hero-tags"><span>NASA NTRS</span><span>NASA FIRMS</span><span>Reproducible local analysis</span></div></section>
<div class="grid three-col section-gap"><article class="panel pitch-card"><span class="kicker">PROBLEM 1</span><h3>Evidence is fragmented</h3><p>Experiment records, publications, and geospatial observations use different formats. Moving from a research question to a verifiable source is difficult.</p></article><article class="panel pitch-card"><span class="kicker">PROBLEM 2</span><h3>Products are not interchangeable</h3><p>MODIS and VIIRS products differ by sensor, resolution, and available fields. Combining them without context can produce misleading comparisons.</p></article><article class="panel pitch-card"><span class="kicker">PROBLEM 3</span><h3>Visuals can overstate the evidence</h3><p>A thermal detection is not a fire perimeter. An uncalibrated image does not provide temperature, and a publication abstract is not raw measurement data.</p></article></div>
<div class="grid cols-main section-gap"><section class="panel"><div class="panel-head"><div><div class="panel-title">What MORS provides</div><div class="panel-subtitle">One research workflow with a clear source for every record</div></div></div><div class="pitch-flow"><div><b>1 · Discover</b><span>NASA NTRS records and archived FIRMS observations.</span></div><i>→</i><div><b>2 · Inspect</b><span>Source, time, product, sensor, and available fields.</span></div><i>→</i><div><b>3 · Analyze</b><span>Local queries, interactive charts, and deterministic tools.</span></div><i>→</i><div><b>4 · Review</b><span>Show values, sources, and limitations before drawing conclusions.</span></div></div><p class="small">Earth observations are a separate supporting module; they do not substitute for spacecraft combustion experiments.</p></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Evidence available for demonstration</div><div class="panel-subtitle">Counts from the local project catalog</div></div></div><div class="pitch-metrics"><div><strong id="pitch-experiments">—</strong><span>NASA combustion records in the experiment catalog</span></div><div><strong id="pitch-publications">—</strong><span>Publication records in the local reference index</span></div><div><strong id="pitch-fires">—</strong><span>FIRMS detections in the local database snapshot</span></div></div><p class="small">These are catalog record counts, not complete experiments or raw combustion measurements, and not the full NASA archive.</p></section></div>
<div class="grid two-col section-gap"><section class="panel"><div class="panel-head"><div><div class="panel-title">What works today?</div><div class="panel-subtitle">Live demonstration sequence</div></div></div><ol class="committee-demo"><li><a href="#research">Open a NASA NTRS record</a><span>Review the abstract and limits on access to original data.</span></li><li><a href="#earth">Open Earth Observatory</a><span>Explore the globe and select a region before requesting FIRMS or GIBS data.</span></li><li><a href="#spacetime">Inspect archived observations</a><span>Hover or select a chart point to view its time, product, value, and source.</span></li><li><a href="#intelligence">Ask the research assistant</a><span>Review the local query result, evidence scope, and available references.</span></li></ol></section><section class="panel"><div class="panel-head"><div><div class="panel-title">What do we not claim?</div><div class="panel-subtitle">Boundaries that protect scientific credibility</div></div></div><ul class="pitch-limits"><li>A complete raw-measurement database for microgravity combustion experiments is not available yet.</li><li>The assistant assembles indexed evidence; it does not replace measurement or scientific review.</li><li>Image analysis is exploratory and does not infer temperature or physical scale without calibration.</li><li>There is no validated predictive model or operational fire alarm.</li></ul><p class="small">Next priority: connect original experiment assets and measurements, then evaluate analyses using independent benchmarks.</p></section></div>
<section class="panel section-gap pitch-close"><span class="kicker">THE CASE FOR MORS</span><h2>The value is not a claim of discovery. It is making available evidence findable, inspectable, and reproducible.</h2><p>This leads to our question for the judges: which spacecraft experiment data should we connect first to test fire-safety hypotheses with comparable measurements?</p><div class="committee-links"><a href="https://ntrs.nasa.gov/citations/19970020606" target="_blank" rel="noopener noreferrer">NASA NTRS · Smoldering in Microgravity ↗</a><a href="https://ntrs.nasa.gov/citations/20210015913" target="_blank" rel="noopener noreferrer">NASA NTRS · ACME on ISS ↗</a><a href="https://firms.modaps.eosdis.nasa.gov/" target="_blank" rel="noopener noreferrer">NASA FIRMS ↗</a></div></section>`}

function missionView(){const m=state.mission||{counts:{verified_experiment_records:0,registered_sources:0,user_uploaded_datasets:0},earth_fire:{status:'Checking',hotspots:null}};const n=m.counts?.verified_experiment_records??0;return `${heading('PRIMARY CHALLENGE · FLAME IN FREEFALL','Mission Control','A unified scientific view of microgravity combustion, experiment context and evidence.','<span class="live-label"><i class="status-dot"></i> SYSTEM ONLINE</span>')}
${missionWorkbench()}
<div class="grid metrics"><div class="metric"><div class="metric-label">INDEXED NASA RECORDS</div><div class="metric-value">${n.toString().padStart(2,'0')}</div><div class="metric-sub"><span class="accent">NTRS</span> metadata & abstracts</div></div><div class="metric"><div class="metric-label">USER-UPLOADED DATASETS</div><div class="metric-value">${String(m.counts?.user_uploaded_datasets??0).padStart(2,'0')}</div><div class="metric-sub">Separate from NASA flight data</div></div><div class="metric"><div class="metric-label">EARTH OBSERVATIONS</div><div class="metric-value">—</div><div class="metric-sub">${esc(m.earth_fire?.status||'Status unavailable')}</div></div><div class="metric"><div class="metric-label">CREW TELEMETRY</div><div class="metric-value">OFF</div><div class="metric-sub">No live sensor feed connected</div></div></div>
${banner('NASA NTRS records and abstracts are verified references, not raw experimental measurements. Live MODIS / VIIRS detections require an official NASA FIRMS MAP_KEY; the map is intentionally not populated with invented hotspots.')}
<div class="grid cols-main">${panel('NASA records by publication year','Computed counts from locally indexed NTRS metadata',`<div class="chart-wrap">${lineChart()}</div><div class="chart-legend"><span><i class="legend-dot" style="background:#55d2e2"></i>Catalog records / publication year</span><span>Descriptive count; not fire activity or experiments count</span></div>`)}${panel('Research brief · NASA NTRS','Source-backed abstract summaries',`<div class="event-list">${state.experiments.slice(0,3).map((e,i)=>`<div class="event"><span class="event-icon">${['◌','◎','⌬'][i]}</span><div><div class="event-name">${esc(e.program)}</div><div class="event-desc">${esc(e.finding.slice(0,153))}…</div></div><span class="event-time">${e.year}</span></div>`).join('')}</div>`)}</div>
<div class="grid cols-main">${panel('Experiment catalog','Primary challenge · selected NASA records',tableRows(state.experiments.slice(0,3)),'')}${panel('Mission data status','Verified sources · ingestion gaps',`<div class="feature-stat"><span>NASA NTRS search</span><strong style="color:var(--green)">VERIFIED</strong></div><div class="feature-stat"><span>NASA FIRMS live feed</span><strong>${esc(m.earth_fire?.status||'Not configured')}</strong></div><div class="feature-stat"><span>RGB vision pipeline</span><strong style="color:var(--green)">AVAILABLE</strong></div><div class="feature-stat"><span>Validated combustion model</span><strong>NOT CONFIGURED</strong></div><div class="feature-stat"><span>Evidence traceability</span><strong style="color:var(--green)">NASA RECORD IDs</strong></div>`)}</div>`}
function tableRows(items){return `<div style="overflow:auto"><table class="experiment-table"><caption class="sr-only">Scientific record catalog</caption><thead><tr><th scope="col">EXPERIMENT / RECORD</th><th scope="col">PROGRAM</th><th scope="col">YEAR</th><th scope="col">EVIDENCE</th></tr></thead><tbody>${items.map(e=>`<tr><td>${sourceLink(e)}<br>${esc(e.title)}</td><td>${esc(e.program)}</td><td>${esc(e.year??'—')}</td><td><span class="pill info">${esc(e.evidence_type||'Metadata record')}</span></td></tr>`).join('')}</tbody></table></div>`}
function experimentsView(){return `${heading('NASA RECORDS · PROVENANCE','Experiment Universe','Browse catalogued research. Abstract-level evidence is distinguished from experimental datasets.')}${banner('Catalog records are sourced from NASA NTRS. A paper abstract is not a replacement for a validated dataset, apparatus metadata or raw measurements.','blue')}${panel('Search experiments','NASA source ID, program, phenomenon or fuel',`<form class="input-row" id="experiment-search"><input id="experiment-query" placeholder="Try “smoldering”, “ACME” or “droplet”" aria-label="Search experiments"><button class="button">Search catalog</button></form><div id="experiment-results">${tableRows(state.experiments)}</div>`)}`}
function dataView(){return `${heading('DATA ACQUISITION · VALIDATION · PROVENANCE','Scientific Data Explorer','Browse the MORS reference catalog, download traceable source data, or upload a measurement CSV for deterministic analysis.')}${banner('Catalog records are real public-source data. Satellite fire detections do not identify ignition cause or fire perimeter; research citations are metadata unless raw measurements are explicitly available.','blue')}${panel(window.MorsI18n?.language==='ar'?'مصادر تجارب الاحتراق':'Combustion experiment sources','NASA PSI',`<div id="combustion-inventory" role="status" aria-live="polite"></div>`)}${panel('MORS space, astronomy and fire reference catalog','Password-protected Excel workbook · verified sources · local downloads',`<div id="science-catalog" class="empty" role="status" aria-live="polite">Loading the local reference catalog…</div>`)}${panel('Ingest a time series','CSV contract: timestamp,value[,unit,experiment_id,sensor,source] · ISO-8601 time · maximum 5,000 rows',`<form id="dataset-upload-form" class="upload-zone"><label for="dataset-file">Choose a time-series CSV for analysis</label><input id="dataset-file" type="file" accept=".csv,text/csv" aria-label="Upload a time-series CSV"><div style="margin-top:12px"><button class="button" type="submit">Validate and analyze</button></div></form><div id="dataset-result" class="section-gap"></div>`)}<div class="section-gap" id="dataset-history">${panel('Previous dataset analyses','Stored locally with content hash and processing history','<div class="empty">Loading dataset history…</div>')}</div>`}
function archiveView(){return `${heading('IMMUTABLE SOURCE ARCHIVE · SHA-256','Raw Data Vault','Browse provider responses exactly as received, their checksums, acquisition queries and provenance.')}${banner('Raw downloads are stored as separate content-addressed files. Searchable observation rows are indexed separately; cleaning or charting never overwrites the source file.','blue')}${panel('Archive capacity','Counts and bytes from the local persistent archive. Satellite snapshots are visual products, not raw instrument granules.',`<div id="archive-summary" class="grid metrics"><div class="metric"><div class="metric-label">RAW OBJECTS</div><div class="metric-value">—</div></div><div class="metric"><div class="metric-label">STORED BYTES</div><div class="metric-value">—</div></div><div class="metric"><div class="metric-label">FIRMS ROWS</div><div class="metric-value">—</div></div><div class="metric"><div class="metric-label">NASA RESEARCH RECORDS</div><div class="metric-value">—</div></div></div><div id="archive-last" class="small">Loading archive status…</div>`)}${panel('Harvest NASA NTRS citation metadata','Search the official NASA Technical Reports Server. Up to 50 citations and abstracts are archived per query; this does not retrieve source experiment measurements.',`<form id="ntrs-harvest-form" class="filter-grid"><label>NASA NTRS query<input id="ntrs-query" maxlength="180" value="microgravity combustion" required></label><button class="button" type="submit">Fetch and archive</button></form><div id="ntrs-harvest-status" class="small section-gap" aria-live="polite">NASA NTRS records are not yet loaded.</div>`)}${panel('Search locally archived research','Records shown here come from the local archive and link to original NASA NTRS citations.',`<form id="ntrs-search-form" class="filter-grid"><label>Title or abstract<input id="ntrs-search-query" maxlength="120" minlength="2" placeholder="combustion, flame spread, safety…"></label><button class="button secondary" type="submit">Search local records</button></form><div id="ntrs-results" class="grid two-col section-gap"><div class="empty">Loading locally indexed NASA records…</div></div>`)}${panel('Archived raw provider files','Download an untouched response and inspect its retrieval query and checksum.',`<div id="archive-table" class="table-scroll"><div class="empty">Loading raw data inventory…</div></div>`)}${panel('Cause investigations and prevention records','FIRMS detections alone do not determine ignition cause. Prevention notes identify their source and geographic scope.',`<div id="cause-guidance" class="grid two-col"><div class="empty">Loading evidence-backed prevention notes…</div></div>`)}`}
function spacetimeView(){const end=new Date().toISOString().slice(0,10),start=new Date(Date.now()-29*86400000).toISOString().slice(0,10);return `${heading('OBSERVATION TIME · COORDINATES · SENSOR','Space-Time Explorer','Filter saved NASA FIRMS observations by acquisition time, sensor product and Earth coordinates; inspect values and plot them.')}${banner('This displays only NASA FIRMS records previously downloaded and archived in Raw Data Vault. Points represent thermal anomalies, not fire perimeters. The cause of an ignition cannot be inferred from these satellite detections.','blue')}${panel('Query the local observation index','UTC date interval · EPSG:4326 bounding box · product-specific records retained',`<form id="space-query" class="filter-grid"><label>Start date (UTC)<input id="space-start" type="date" value="${start}"></label><label>End date (UTC)<input id="space-end" type="date" value="${end}"></label><label>West longitude<input id="space-west" type="number" step="any" min="-180" max="180" value="-119"></label><label>South latitude<input id="space-south" type="number" step="any" min="-90" max="90" value="33"></label><label>East longitude<input id="space-east" type="number" step="any" min="-180" max="180" value="-118"></label><label>North latitude<input id="space-north" type="number" step="any" min="-90" max="90" value="34"></label><label>Sensor product<select id="space-product"><option value="">All archived products</option>${['VIIRS_SNPP_NRT','VIIRS_SNPP_SP','VIIRS_NOAA20_NRT','VIIRS_NOAA20_SP','VIIRS_NOAA21_NRT','VIIRS_NOAA21_SP','MODIS_NRT','MODIS_SP'].map(x=>`<option value="${x}">${x}</option>`).join('')}</select></label><button class="button" type="submit">Query observations</button></form><div id="space-query-status" class="small section-gap">Choose a bounded region and date range, then query.</div>`)}<div class="grid two-col section-gap">${panel('Daily detection rate','Archived observations in the selected filters; the plot shows the last 60 calendar days with product-specific bars.',`<div id="space-time-chart" class="chart-wrap"><div class="empty">Run a query to plot time-series values.</div></div><p class="small">Rate = daily count / 1 day. This is a count rate, not fire area or severity.</p>`)}${panel('FRP vs brightness temperature','Only the current page of up to 200 records is plotted. Change pages to inspect other records. FRP is not a fire perimeter or measured flame temperature.',`<div id="space-scatter-chart" class="chart-wrap"><div class="empty">Run a query to plot available values.</div></div><p class="small">x = brightness temperature (K); y = reported FRP (MW). Missing values are omitted from the plotted sample.</p>`)}</div>${panel('Prevention evidence','Causes require separate ground investigation records. General guidance below is sourced and geographically limited.',`<div id="space-guidance" class="grid two-col"><div class="empty">Loading evidence-backed prevention notes…</div></div>`)}${panel('Observation records','First page only; export the page or move through paginated results.',`<div class="data-table-toolbar"><span id="space-page-count" class="small">No query yet.</span><button id="space-export" class="button secondary" type="button" disabled>Export page CSV</button><span class="spacer"></span><button id="space-prev" class="button secondary" type="button" disabled>Previous</button><button id="space-next" class="button secondary" type="button" disabled>Next</button></div><div id="space-table" class="table-scroll"><div class="empty">No query loaded.</div></div>`)}`}
function quantumView(){return `${heading('QUANTUM COMPUTING · RESEARCH LAB','Quantum Lab','Build and run reproducible small-circuit simulations, inspect state and compare a quantum feature kernel with a classical baseline.','<span class="live-label"><i class="status-dot"></i> LOCAL SIMULATION</span>')}${banner('No quantum hardware is connected. Qiskit Aer or the deterministic NumPy reference backend simulates circuits on classical hardware; this is not quantum hardware execution and does not establish quantum advantage.','blue')}<div class="grid cols-main">${panel('Circuit workbench','Bell pair · H(q0) → CX(q0,q1)',`<div class="quantum-top"><label>Pattern <select id="q-pattern" class="select-input"><option value="bell">Bell entanglement</option><option value="superposition">Single-qubit superposition</option><option value="ghz">Three-qubit GHZ</option><option value="custom">Custom circuit</option></select></label><label>Qubits <select id="q-qubits" class="select-input"><option>1</option><option selected>2</option><option>3</option><option>4</option></select></label><label>Shots <input id="q-shots" class="select-input" type="number" min="128" max="8192" step="128" value="2048"></label><label>Seed <input id="q-seed" class="select-input" type="number" min="0" max="4294967295" value="41"></label></div><div class="quantum-circuit" id="q-circuit"></div><button id="q-run" class="button">Run reproducible experiment</button><div id="q-result" class="section-gap"></div>`)}${panel('Circuit library','Gate semantics and local backend',`<div class="event-list"><div class="event"><span class="event-icon">H</span><div><div class="event-name">Hadamard</div><div class="event-desc">Creates computational-basis superposition.</div></div></div><div class="event"><span class="event-icon">CX</span><div><div class="event-name">Controlled-X</div><div class="event-desc">Entangles superposition control with target.</div></div></div><div class="event"><span class="event-icon">RZ</span><div><div class="event-name">Parameterized rotations</div><div class="event-desc">Unitary single-qubit rotations with angle in radians.</div></div></div><div class="source-note">Statevector is an ideal pure-state model. Counts use a fixed pseudo-random seed; simulator noise and device calibration are not modeled.</div></div>`)}</div><div id="q-benchmark" class="section-gap"></div><div id="q-history" class="section-gap"></div>`}
function combustionView(){return `${heading('COMPUTER VISION · LAB','Combustion Lab','Explore conservative flame-image segmentation with explicit uncertainty and no uncalibrated temperature claims.')}${banner('RGB color thresholding is an exploratory pixel heuristic, not a validated flame classifier. Ordinary RGB brightness does not measure temperature. Results need labeled scientific images and expert review.')}${panel('NASA BASS-II experimental table','PSI-25 · International Space Station · source table version 1',`<div id="bass-lab"><p class="bass-status" role="status">${window.MorsI18n?.language==='ar'?'جارٍ تحميل جدول ناسا والتحقق من بصمته…':'Loading the NASA source table and checking its checksum…'}</p><div class="input-row"><label>${window.MorsI18n?.language==='ar'?'التجربة الأولى':'First test'} <select disabled aria-label="${window.MorsI18n?.language==='ar'?'التجربة الأولى':'First test'}"></select></label><label>${window.MorsI18n?.language==='ar'?'التجربة الثانية':'Second test'} <select disabled aria-label="${window.MorsI18n?.language==='ar'?'التجربة الثانية':'Second test'}"></select></label></div><div class="bass-result section-gap"></div><p class="small">${window.MorsI18n?.language==='ar'?'القيم من جدول ناسا الأصلي. بعض الخانات مفقودة أو نصية. اختلاف ظروف العينات يمنع اعتبار المقارنة إثباتاً لعلاقة سببية.':'Values are reproduced from NASA’s source table. Some entries are missing or textual. Different sample conditions limit comparisons and do not establish causation.'}</p><p class="small"><a href="https://psi.nasa.gov/physci/repo/data/investigations/PSI-25" target="_blank" rel="noreferrer">NASA PSI-25 ↗</a> · <a href="/bass-ii-experiment-table.csv" download>CSV ↗</a> · SHA-256 <bdi dir="ltr">71e792bf6b5fb5ea620c5dd70fbbac05515992e12aefcf5dff47312caa48c042</bdi></p></div>`)}${panel('Image analysis','Upload PNG · JPEG · WebP · Maximum 12 MiB',`<div class="upload-zone">Select a combustion image for pixel segmentation.<input id="image-upload" type="file" accept="image/png,image/jpeg,image/webp" aria-label="Upload a combustion image"></div><div id="vision-result" class="section-gap"></div>`)}`}
function intelligenceView(){return `${heading('SCIENTIFIC AI · LOCAL EVIDENCE','Scientific Research Copilot','Ask a research question. The assistant queries indexed records and deterministic tools, then states evidence and limitations.')}${banner('Local catalog coverage varies by topic. NASA publication metadata and archived Earth-observation records are available; raw microgravity experiment measurements may be absent. The assistant must say when the evidence cannot answer a question.','blue')}<div class="grid cols-main"><section class="panel science-chat-panel"><div class="panel-head"><div><div class="panel-title">Research question</div><div class="panel-subtitle">Arabic and English · source-grounded · no unsupported measurements</div></div><span class="tag">LOCAL MODEL</span></div><div class="science-prompts"><button type="button" class="button secondary ai-prompt" data-prompt="What does the local NASA research catalog say about microgravity combustion, and what data are missing?">Microgravity evidence</button><button type="button" class="button secondary ai-prompt" data-prompt="Summarize the archived FIRMS observations by product and explain their limits.">FIRMS archive summary</button></div><form id="ai-chat-form" class="science-chat-form"><label for="ai-question">Your scientific question</label><textarea id="ai-question" rows="4" maxlength="4000" required placeholder="Ask a scientific question about the available data and evidence…"></textarea><div class="chat-form-footer"><span class="small">The system will query local data and show its evidence scope and limitations.</span><button class="button" type="submit">Analyze evidence</button></div></form><div id="ai-answer" class="section-gap" aria-live="polite"></div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Analysis protocol</div><div class="panel-subtitle">What the assistant does for each question</div></div></div><ol class="science-steps"><li><b>Retrieve</b><span>Search indexed NASA and FIRMS records.</span></li><li><b>Calculate</b><span>Run deterministic database summaries where supported.</span></li><li><b>Qualify</b><span>Separate recorded values, interpretations, and missing evidence.</span></li><li><b>Trace</b><span>Expose source IDs and retrieval output for review.</span></li></ol><div id="ai-model-status" class="source-note section-gap" role="status">Checking local model availability…</div><a class="small" href="#methodology">Review scientific methodology ↗</a></section></div>`}

function earthView(){return `${heading('EARTH OBSERVATIONS · SEPARATE MODULE','Earth Fire Observatory','Inspect authentic NASA FIRMS thermal anomalies. Satellite detections are not confirmed wildfire boundaries or spacecraft combustion.')}
${banner('Choose a bounded region or request one global day. MODIS and VIIRS product labels remain separate.','blue')}
<section class="earth-guide" aria-label="${window.MorsI18n?.language==='ar'?'خطوات استكشاف الرصدات':'Observation workflow'}">
  <div><span class="earth-guide-icon" aria-hidden="true">◎</span><strong>${window.MorsI18n?.language==='ar'?'استكشف الرصدات':'Explore observations'}</strong><p>${window.MorsI18n?.language==='ar'?'اختر نقطة على الكرة لعرض موقعها وبياناتها.':'Select a point on the globe to inspect its location and data.'}</p></div>
  <div><span class="earth-guide-icon" aria-hidden="true">⌖</span><strong>${window.MorsI18n?.language==='ar'?'حدّد منطقة':'Choose a region'}</strong><p>${window.MorsI18n?.language==='ar'?'استخدم الموقع المحدد لتعبئة إحداثيات البحث.':'Use the selected location to fill the search coordinates.'}</p></div>
  <div><span class="earth-guide-icon" aria-hidden="true">↗</span><strong>${window.MorsI18n?.language==='ar'?'راجع البيانات':'Review data'}</strong><p>${window.MorsI18n?.language==='ar'?'افتح مستكشف الزمكان لتصفية الرصدات المؤرشفة.':'Open Space-Time Explorer to filter archived observations.'}</p><a href="#spacetime">${window.MorsI18n?.language==='ar'?'فتح مستكشف الزمكان':'Open Space-Time Explorer'}</a></div>
</section>
${panel('Earth globe and NASA satellite image','The globe is a NASA shaded-relief visualization. The adjacent image is date-specific corrected-reflectance imagery from NASA GIBS; FIRMS anomaly points are separate observations.',`<div class="earth-media-grid"><figure class="earth-figure"><div class="globe-stage"><canvas id="fire-globe" width="900" height="480" tabindex="0" role="application" aria-label="Interactive Earth globe. Drag to rotate, use plus and minus to zoom, and click a location or hotspot."></canvas><div class="globe-tools" role="group" aria-label="Earth globe controls"><button type="button" id="globe-zoom-in" aria-label="Zoom in">+</button><output id="globe-zoom-level" aria-label="Zoom level">100%</output><button type="button" id="globe-zoom-out" aria-label="Zoom out">−</button><button type="button" id="globe-reset">Reset view</button></div></div><figcaption>Drag to rotate · scroll or pinch to zoom · click or tap to select</figcaption><div class="globe-legend"><span><i></i> FIRMS thermal anomaly</span><button type="button" id="globe-load-archive" class="button secondary">Show archived observations</button></div><div class="globe-selection"><span id="globe-selection" role="status" aria-live="polite">No location selected.</span><button type="button" id="globe-use-selection" class="button secondary" disabled>Use selected location</button></div></figure><figure class="earth-figure"><div class="satellite-frame"><img id="satellite-snapshot" alt="Date-specific NASA satellite corrected-reflectance image for the selected region" hidden><div id="satellite-placeholder" class="empty">Choose a date and load a real NASA satellite image for the selected coordinates.</div></div><figcaption>NASA GIBS / Worldview · corrected reflectance, not a fire perimeter</figcaption></figure></div><div id="globe-status" class="small section-gap">Load an area below to retrieve observations; drag the globe to rotate it.</div><div id="satellite-status" class="small">Satellite imagery has not been requested.</div>`)}
${panel('Load authentic satellite data','NASA FIRMS observations require MAP_KEY. Satellite reflectance snapshots use NASA Worldview / GIBS.',`<form id="firms-form" class="input-row"><label>FIRMS region <select id="firms-region" class="select-input"><option value="area">Selected coordinates</option><option value="world">Worldwide, one day</option></select></label><label>West <input id="firms-west" type="number" min="-180" max="180" step="any" value="-119" required></label><label>South <input id="firms-south" type="number" min="-90" max="90" step="any" value="33" required></label><label>East <input id="firms-east" type="number" min="-180" max="180" step="any" value="-118" required></label><label>North <input id="firms-north" type="number" min="-90" max="90" step="any" value="34" required></label><label>FIRMS product <select id="firms-source" class="select-input"><option>VIIRS_SNPP_NRT</option><option>VIIRS_NOAA20_NRT</option><option>VIIRS_NOAA21_NRT</option><option>MODIS_NRT</option><option>MODIS_SP</option></select></label><label>Days <select id="firms-days" class="select-input"><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option></select></label><button class="button" type="submit">Download and archive FIRMS data</button></form><form id="snapshot-form" class="input-row snapshot-form"><label>Image date (UTC) <input id="snapshot-date" type="date" required></label><label>Image sensor<select id="snapshot-sensor" class="select-input"><option value="VIIRS">VIIRS Suomi-NPP</option><option value="MODIS">MODIS Terra</option></select></label><button class="button secondary" type="submit">Load satellite image</button></form><div id="firms-results" role="status" aria-live="polite">Choose a region to request observations.</div>`)}
${panel('Interpretation','Source and uncertainty',`<p>FIRMS identifies satellite thermal anomalies. Confidence, instrument, acquisition time and processing version are preserved per record. A point is not an exact fire boundary. <a href="https://firms.modaps.eosdis.nasa.gov/api/area" target="_blank" rel="noreferrer">NASA FIRMS API documentation ↗</a></p>`)} `}
function environmentView(){return `${heading('SPACECRAFT CONTEXT · RESEARCH','Space Environment','A research context for published spacecraft fire studies; no operational telemetry is connected.')}${banner('No live spacecraft environmental or crew telemetry is configured. There are no validated readings here; this module does not make medical diagnoses or issue emergency procedures.')}${panel('Environmental data channels','Measurements appear only when a verified source and units are available',`<div class="grid three-col"><div class="list-card"><div class="meta">AIR COMPOSITION</div><h3>Not connected</h3><p>Oxygen, carbon dioxide and pressure require an identified instrument feed, timestamps, units and quality flags.</p></div><div class="list-card"><div class="meta">SMOKE / AEROSOLS</div><h3>Research context only</h3><p>NASA NTRS records include spacecraft smoke detection studies; this app has no live smoke measurement.</p><a href="https://ntrs.nasa.gov/citations/20010074094" target="_blank" rel="noreferrer">NASA NTRS: SMOKE record ↗</a></div><div class="list-card"><div class="meta">CREW WELLBEING</div><h3>No medical inference</h3><p>Environmental indicators alone cannot establish a medical condition or replace crew health monitoring.</p></div></div>`)}`}
function twinView(){return `${heading('PARAMETRIC EXPLORATION · NOT A SOLVER','Digital Twin','Explore scenario inputs without presenting hypothetical output as a NASA observation.')}${banner('No validated combustion predictive model is configured. The controls below show experimental scenario parameters only; there are no simulated flame-spread, extinction or heat-release predictions.','blue')}${panel('Scenario parameters','Interactive inputs · output remains intentionally unavailable',`<form id="twin-form"><div class="slider-row"><label for="oxygen">Oxygen fraction</label><input type="range" min="10" max="40" value="21" step="1" id="oxygen"><output id="oxygen-out">21 %</output></div><div class="slider-row"><label for="pressure">Pressure</label><input type="range" min="20" max="200" value="101" step="1" id="pressure"><output id="pressure-out">101 kPa</output></div><div class="slider-row"><label for="flow">Flow velocity</label><input type="range" min="0" max="2" value="0.2" step="0.1" id="flow"><output id="flow-out">0.2 m/s</output></div><button class="button">Record exploratory scenario</button></form><div id="twin-result" class="section-gap"></div>`)}`}
function safetyView(){return `${heading('EVIDENCE · LIMITATIONS · RESEARCH RELEVANCE','Safety Intelligence','Trace a research observation back to the source record before drawing implications.')}${banner('These records provide scientific context, not validated spacecraft hazard classifications, operating procedures or fire-prevention guarantees.')}${state.experiments.map(e=>`<div class="panel section-gap"><div class="panel-head"><div><div class="panel-title">${esc(e.title)}</div><div class="panel-subtitle">${esc(e.program)} · source record ${esc(e.source_id)}</div></div><span class="pill info">OBSERVED · ABSTRACT</span></div><div class="quote">${esc(e.finding)}</div><div class="grid two-col section-gap"><div><div class="label-mini">SOURCE EXPERIMENT</div><p class="small">${esc(e.evidence_type)} · ${sourceLink(e)}</p></div><div><div class="label-mini">METHOD / LIMITATIONS</div><p class="small">NASA NTRS indexed abstract; original numerical data and apparatus-level comparability were not assessed. ${esc(e.limits)}</p></div></div></div>`).join('')}`}
function researchView(){return `${heading('SOURCE TRACEABILITY · NASA NTRS','Research Explorer','Locate source records, inspect abstracts and retain the original citation in each result.')}${panel('Indexed scientific records','All records link to NASA NTRS',`<div class="grid two-col">${state.experiments.map(e=>`<article class="list-card"><div class="meta">NASA NTRS · ${e.source_id} · ${e.year}</div><h3>${esc(e.title)}</h3><p>${esc(e.finding)}</p><p class="small">${esc(e.limits)}</p>${sourceLink(e)}</article>`).join('')}</div>`)}`}
function architectureView(){return `${heading('INDEPENDENT ENGINES · STATUS','System Architecture','Implemented capabilities and gaps are visible; planned agents are not misrepresented as deployed.')}${banner('Specialized AI agents are shown as a target workflow architecture. This deployment does not operate autonomous agent processes.','blue')}${panel('Evidence pipeline','Source → data → analysis → validation → display',`<div class="arch-flow">${['NASA NTRS / FIRMS','Source adapters','Metadata & SQLite','Analysis / vision','Validation gates','Evidence UI'].map((x,i)=>`${i?'<span class="arch-arrow">→</span>':''}<span class="arch-node">${x}</span>`).join('')}</div>`)}<div class="grid two-col section-gap">${panel('Implemented in this build','Application capabilities',`<div class="feature-stat"><span>FastAPI health and catalog APIs</span><strong>READY</strong></div><div class="feature-stat"><span>SQLite provenance schema</span><strong>READY</strong></div><div class="feature-stat"><span>NASA NTRS metadata catalog</span><strong>3 RECORDS</strong></div><div class="feature-stat"><span>RGB image threshold / overlay</span><strong>EXPLORATORY</strong></div><div class="feature-stat"><span>Lexical research search</span><strong>LOCAL ABSTRACTS</strong></div>`)}${panel('Not yet connected','Honest integration gaps',`<div class="feature-stat"><span>MODIS / VIIRS live observations</span><strong>MAP_KEY REQUIRED</strong></div><div class="feature-stat"><span>Vector DB / generative RAG</span><strong>NOT BUILT</strong></div><div class="feature-stat"><span>NASA raw imagery ingestion</span><strong>NOT BUILT</strong></div><div class="feature-stat"><span>Predictive combustion model</span><strong>NOT VALIDATED</strong></div><div class="feature-stat"><span>Spacecraft telemetry</span><strong>NOT CONNECTED</strong></div>`)}</div>${panel('Target multi-agent roles','Architecture intent only',`<div class="grid three-col">${['Research Agent','Data Engineering Agent','Computer Vision Agent','Scientific Analysis Agent','Intelligence Agent','Visualization Agent','Validation Agent','Orchestrator Agent'].map((a,i)=>`<div class="list-card"><div class="meta">ENGINE ${String(i+1).padStart(2,'0')}</div><h3>${a}</h3><p>Specified role; no autonomous agent execution is configured.</p></div>`).join('')}</div>`)}`}
function methodologyView(){return `${heading('MEASUREMENT DISCIPLINE · REPRODUCIBILITY','Methodology','Show what was observed, computed, inferred or left unknown.')}${panel('Evidence classifications','Kept distinct throughout the API and interface',`<div class="grid three-col">${[['OBSERVED DATA','NASA NTRS record / abstract text. Does not imply the raw instrument dataset is present.'],['COMPUTED RESULTS','Deterministic local processing outputs, e.g. RGB threshold pixel area.'],['MODEL ESTIMATES','No predictive combustion model is currently configured.'],['AI INTERPRETATIONS','Metadata-level synthesis; quantitative claims are withheld without measurements.'],['HYPOTHESES','Scenario controls record input parameters only. No prediction is asserted.']].map(([t,d])=>`<div class="list-card"><div class="meta">EVIDENCE CLASS</div><h3>${t}</h3><p>${d}</p></div>`).join('')}</div>`)}<div class="grid two-col section-gap">${panel('Image segmentation','Reproducible heuristic',`<div class="code-block">R &gt; 150<br>R &gt; 1.12 × G<br>G &gt; 1.05 × B<br>R − B &gt; 35<br><br>Threshold → warm-pixel mask → bounding box + overlay<br>No calibrated scale · no temperature estimate · not validated against a labeled flame dataset</div>`)}${panel('Comparability gate','Avoid unlike-with-unlike',`<p class="small">Before quantitative cross-experiment analysis, verify apparatus, fuel, oxygen fraction, pressure, gravity level, flow conditions, diagnostics, calibration, units and collection metadata. The available abstract records lack a common numerical measurement schema; this system declines quantitative comparisons.</p><p class="small">Earth observation comparisons retain MODIS / VIIRS sensor and product identity. Active fire detection is not spacecraft combustion data.</p>`)}</div>${panel('NASA source ledger','Official NASA reference endpoints verified',`<div class="event-list"><div class="event"><div class="event-icon">N</div><div><div class="event-name">NASA NTRS · 1997 microgravity smoldering abstract</div><div class="event-desc">NASA record ${sourceLink(state.experiments[0])} · metadata and abstract queried through NASA NTRS search API.</div></div></div><div class="event"><div class="event-icon">N</div><div><div class="event-name">NASA NTRS · ACME poster abstract</div><div class="event-desc">NASA record ${sourceLink(state.experiments[1])} · ACME on ISS; NASA poster metadata.</div></div></div><div class="event"><div class="event-icon">F</div><div><div class="event-name">NASA EOSDIS FIRMS</div><div class="event-desc"><a href="https://firms.modaps.eosdis.nasa.gov/api/area/" target="_blank" rel="noreferrer">Area API</a> · official access mechanism verified; a MAP_KEY is required to retrieve observations.</div></div></div></div>`)}`}
function aboutView(){return `${heading('TEAM MORS · SPACE APPS CHALLENGE 2026','MORS AEGIS','Intelligent fire safety for human space exploration.')}${panel('Mission statement','Primary challenge · Flame in Freefall',`<p class="quote">Connect verifiable microgravity combustion research, source-traceable experiment metadata and interpretable safety context—without blurring measured evidence with hypotheses.</p><div class="grid three-col section-gap"><div class="list-card"><div class="meta">PRIMARY</div><h3>Microgravity combustion</h3><p>Flame behavior, ignition, spread and extinction are understood in their specific experimental context.</p></div><div class="list-card"><div class="meta">SUPPORTING</div><h3>Earth observation</h3><p>Separate analysis of NASA MODIS and VIIRS terrestrial fire observations.</p></div><div class="list-card"><div class="meta">SAFETY</div><h3>Traceable insight</h3><p>Each scientific claim carries source, method, uncertainty and stated limitations.</p></div></div><p class="small">Built by Team MORS · NASA Space Apps Challenge 2026 · References originate from NASA NTRS and NASA EOSDIS FIRMS. This research platform does not provide operational emergency guidance or medical diagnosis.</p>`)}`}
const views={mission:missionView,experiments:experimentsView,data:dataView,gallery:galleryView,archive:archiveView,spacetime:spacetimeView,quantum:quantumView,combustion:combustionView,intelligence:intelligenceView,earth:earthView,environment:environmentView,twin:twinView,safety:safetyView,research:researchView,architecture:architectureView,methodology:methodologyView,about:aboutView,pitch:committeeView};
function render(view=state.view){state.view=views[view]?view:'mission';const item=navItems.find(x=>x[0]===state.view);const localeText=value=>window.MorsI18n?.text(value)||value;$('#crumb').textContent=localeText(item?.[1]||'Mission Control').toUpperCase();document.title=`${localeText(item?.[1]||'Mission Control')} | MORS AEGIS`;document.querySelectorAll('.nav-item').forEach(a=>{const active=a.dataset.view===state.view;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});try{$('#view-content').innerHTML=`<div id="global-science-ribbon"></div>${views[state.view]()}`;bindView()}catch(err){$('#view-content').innerHTML=`<section class="panel" role="alert"><h1>View unavailable</h1><p>${esc(err.message)}</p><button class="button" type="button" id="retry-view">Retry</button></section>`;$('#retry-view').addEventListener('click',()=>render(state.view))}}
function bindView(){bindGlobalScienceRibbon();if(state.view==='mission'){bindMissionChart();bindMissionWorkbench()}if(state.view==='quantum')bindQuantumView();if(state.view==='data'){bindDataView();bindScienceCatalog();bindCombustionInventory();bindCombustionIndex()}if(state.view==='gallery')bindGalleryView();if(state.view==='archive')bindArchiveView();if(state.view==='spacetime')bindSpaceTimeView();if(state.view==='earth')bindEarthView();if(state.view==='intelligence')bindAIView();if(state.view==='combustion'){bindBassLab();bindBassOverview();bindFlameDesign();bindCoolFlames();bindCombustionReferences();bindFlexLab();bindVisionLab()}bindOtherViews()}
async function bindAIView(){let bassSelection=null,flameSelection=null,coolSelection=null;try{const saved=JSON.parse(sessionStorage.getItem('mors-bass-selection'));if(Array.isArray(saved)&&saved.length===2&&saved.every(Number.isInteger)){bassSelection=saved;sessionStorage.removeItem('mors-bass-selection');const ar=window.MorsI18n?.language==='ar';$('#ai-question').value=ar?'قارن قيم تجربتي BASS-II المحددتين واشرح حدود المقارنة.':'Compare the selected BASS-II tests and explain the limits.';$('#ai-question').insertAdjacentHTML('beforebegin',`<p class="source-note">${ar?'تم إرفاق التجربتين المحددتين من مختبر الاحتراق بهذا السؤال.':'The two tests selected in Combustion Lab are attached to this question.'}</p>`)}}catch{}try{const saved=JSON.parse(sessionStorage.getItem('mors-flame-selection'));sessionStorage.removeItem('mors-flame-selection');if(saved&&['normal','inverse'].includes(saved.configuration)&&Number.isInteger(saved.row_index)&&saved.row_index>=0){flameSelection=saved;bassSelection=null;const ar=window.MorsI18n?.language==='ar';$('#ai-question').value=ar?'اشرح القيم المسجلة في اختبار ACME المختار وحدودها.':'Explain the selected ACME test values and their limitations.';$('#ai-question').insertAdjacentHTML('beforebegin',`<p class="source-note">${ar?'تم إرفاق سجل ACME المحدد من مختبر الاحتراق.':'The selected ACME record is attached from Combustion Lab.'}</p>`)}}catch{}try{const saved=JSON.parse(sessionStorage.getItem('mors-cool-selection'));sessionStorage.removeItem('mors-cool-selection');if(saved&&['normal','inverse'].includes(saved.configuration)&&typeof saved.fuel==='string'&&saved.fuel.length<=100){coolSelection=saved;bassSelection=null;flameSelection=null;const ar=window.MorsI18n?.language==='ar';$('#ai-question').value=ar?'اشرح بيانات CFI-G المحددة، وحجم العينة، وحدود الاستنتاج.':'Explain the selected CFI-G data, sample size, and limitations.';$('#ai-question').insertAdjacentHTML('beforebegin',`<p class="source-note cool-selection-note">${ar?'تم إرفاق تحديد CFI-G من مختبر الاحتراق.':'The CFI-G selection from Combustion Lab is attached.'} <button type="button" class="button secondary clear-cool-selection">${ar?'إزالة التحديد':'Remove selection'}</button></p>`);$('.clear-cool-selection').addEventListener('click',()=>{coolSelection=null;$('.cool-selection-note')?.remove()})}}catch{}const modelStatus=$('#ai-model-status');try{const d=await request('/integrations/status');const local=Object.entries(d).find(([k,v])=>/ollama/i.test(k+' '+v.provider));modelStatus.textContent=local?`Local model service: ${local[1].configured?'configured; run a question to verify the selected model':'not configured'}. Answers fall back to deterministic local tools when unavailable.`:'Local model status could not be identified. Deterministic local science tools remain available.'}catch(e){modelStatus.textContent=`Model status unavailable: ${e.message}. Deterministic local tools may still answer supported queries.`}document.querySelectorAll('.ai-prompt').forEach(b=>b.addEventListener('click',()=>{$('#ai-question').value=b.dataset.prompt;$('#ai-question').focus()}));$('#ai-chat-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type=submit]'),out=$('#ai-answer');button.disabled=true;out.innerHTML='<div class="source-note">Retrieving indexed evidence and running supported local analyses…</div>';try{const d=await request('/ai/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:$('#ai-question').value,bass_selection:bassSelection,flame_selection:flameSelection,cool_selection:coolSelection})});const citations=Array.isArray(d.tool_result?.records)?d.tool_result.records:[];const citationHtml=citations.slice(0,8).map(x=>{const url=x.record||x.url||x.source_url;const title=x.title||x.id||'Source record';return url&&/^https:\/\//i.test(url)?`<li><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗</a><span>${esc(x.id||'')}</span></li>`:`<li>${esc(title)} <span>${esc(x.id||'')}</span></li>`}).join('');out.innerHTML=`<article class="science-answer"><header><div><span class="kicker">EVIDENCE-BASED RESPONSE</span><h3>${esc(d.provider||'Local science tools')}${d.model?` · ${esc(d.model)}`:''}</h3></div><span class="tag">${d.ai_status?esc(d.ai_status):'ANALYSIS COMPLETE'}</span></header><p class="science-answer-text">${esc(d.answer).replaceAll('\n','<br>')}</p><div class="source-note"><strong>Evidence scope</strong><br>${esc(d.evidence_scope||'Local indexed records and deterministic tools.')}</div>${citationHtml?`<div class="section-gap"><strong>Retrieved sources</strong><ul class="science-citations">${citationHtml}</ul></div>`:''}${d.tool_result?`<details class="section-gap"><summary>Inspect retrieved records and calculations</summary><pre class="code-block">${esc(JSON.stringify(d.tool_result,null,2))}</pre></details>`:''}</article>`}catch(err){out.innerHTML=`<div class="source-note" role="alert">Analysis request failed: ${esc(err.message)}</div>`}finally{button.disabled=false}})}
function formatBytes(value){let n=Number(value)||0;for(const unit of ['B','KB','MB','GB','TB']){if(n<1024||unit==='TB')return `${n.toFixed(unit==='B'?0:1)} ${unit}`;n/=1024}return `${n.toFixed(1)} TB`}
