function attachChartInspector(host,selector,rows,describe){let detail=host.querySelector('.chart-point-detail');if(!detail){detail=document.createElement('div');detail.className='chart-point-detail';detail.setAttribute('aria-live','polite');detail.setAttribute('role','status');detail.textContent='Select or hover over a point or bar to inspect its values and source.';host.append(detail)}host.querySelectorAll(selector).forEach(el=>{const show=()=>{const row=rows[Number(el.dataset.point)];if(row)detail.textContent=describe(row)};el.addEventListener('pointerenter',show);el.addEventListener('focus',show);el.addEventListener('click',show);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show()}})})}
function bindMissionChart(){const grouped=new Map();state.experiments.forEach(x=>{const year=Number(x.year);grouped.set(year,(grouped.get(year)||0)+1)});const rows=[...grouped].sort((a,b)=>a[0]-b[0]).map(([year,count])=>({year,count}));const host=document.querySelector('.cols-main .chart-wrap');if(host&&rows.length)attachChartInspector(host,'.chart-point',rows,x=>`${x.year} · ${x.count.toLocaleString()} indexed NASA catalog records for this publication year. These are metadata records, not experiment counts or combustion measurements.`)}
function renderDailyChart(rows){const host=$('#space-time-chart');if(!rows.length){host.innerHTML='<div class="empty">No archived observations in this filter.</div>';return}const valid=rows.filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x.day_utc)&&Number.isFinite(Date.parse(x.day_utc+'T00:00:00Z')));if(!valid.length){host.innerHTML='<div class="empty">No valid observation dates to plot.</div>';return}const last=Math.max(...valid.map(x=>Date.parse(x.day_utc+'T00:00:00Z'))),first=last-59*86400000,a=valid.filter(x=>Date.parse(x.day_utc+'T00:00:00Z')>=first),products=[...new Set(a.map(x=>x.product))],max=Math.max(1,...a.map(x=>Number(x.n))),w=700,h=230,p=48,dayWidth=(w-2*p)/60,bw=Math.max(1,(dayWidth-1)/products.length),colors=['#55cadb','#e5a94b','#91baee','#d381bb','#7bcda2','#f28c75','#c5a9ed','#ded276'];host.innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Daily count of archived NASA FIRMS observations; select a bar for values"><line x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}" class="chart-grid"/><line x1="${p}" y1="${p}" x2="${p}" y2="${h-p}" class="chart-grid"/><text x="4" y="${p+3}" class="chart-axis">${max}</text><text x="${p}" y="${h-8}" class="chart-axis">${new Date(first).toISOString().slice(0,10)}</text><text x="${w-p}" y="${h-8}" text-anchor="end" class="chart-axis">${new Date(last).toISOString().slice(0,10)}</text>${a.map((x,i)=>{const day=Math.round((Date.parse(x.day_utc+'T00:00:00Z')-first)/86400000),pi=products.indexOf(x.product),bh=(Number(x.n)/max)*(h-2*p);return `<rect class="chart-point" data-point="${i}" tabindex="0" role="button" aria-label="${esc(x.day_utc)}, ${esc(x.product)}, ${x.n} observations" x="${(p+day*dayWidth+pi*bw).toFixed(2)}" y="${(h-p-bh).toFixed(2)}" width="${bw.toFixed(2)}" height="${bh.toFixed(2)}" fill="${colors[pi%colors.length]}"><title>${esc(x.day_utc)} · ${esc(x.product)} · ${x.n} observations/day</title></rect>`}).join('')}</svg><div class="chart-point-detail" role="status" aria-live="polite">Hover over, focus, or select a bar to inspect its archived values.</div><p class="small">Last 60 calendar days ending ${new Date(last).toISOString().slice(0,10)}; gaps indicate no archived detections for that day. Separate bars represent different products.</p>`;attachChartInspector(host,'.chart-point',a,x=>`${x.day_utc} UTC · ${x.product} · ${Number(x.n).toLocaleString()} observations/day · mean FRP ${x.mean_frp_mw===null?'unavailable':Number(x.mean_frp_mw).toFixed(2)+' MW'} · archived FIRMS records.`)}
function renderFRPScatter(items){const host=$('#space-scatter-chart'),points=items.filter(x=>x.bright_ti4_k!==null&&x.frp_mw!==null&&Number.isFinite(Number(x.bright_ti4_k))&&Number.isFinite(Number(x.frp_mw)));if(!points.length){host.innerHTML='<div class="empty">No brightness / FRP pairs in the current page.</div>';return}const vals=points.map(x=>[Number(x.bright_ti4_k),Number(x.frp_mw)]),xmin=Math.min(...vals.map(x=>x[0])),xmax=Math.max(...vals.map(x=>x[0])),ymin=Math.min(0,...vals.map(x=>x[1])),ymax=Math.max(1,...vals.map(x=>x[1])),w=700,h=190,p=42;host.innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Archived FIRMS brightness temperature versus fire radiative power; select a point for source values"><line x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}" class="chart-grid"/><line x1="${p}" y1="${p}" x2="${p}" y2="${h-p}" class="chart-grid"/><text x="${w/2}" y="${h-5}" text-anchor="middle" class="chart-axis">Brightness temperature (K)</text><text x="4" y="${p}" class="chart-axis">FRP MW</text>${vals.map(([x,y],i)=>{const sx=p+(x-xmin)/Math.max(1e-9,xmax-xmin)*(w-2*p),sy=h-p-(y-ymin)/Math.max(1e-9,ymax-ymin)*(h-2*p);return `<circle class="chart-point" data-point="${i}" tabindex="0" role="button" aria-label="TI4 ${x.toFixed(2)} K, FRP ${y.toFixed(2)} MW, ${esc(points[i].observed_at_utc)}" cx="${sx.toFixed(2)}" cy="${sy.toFixed(2)}" r="4" fill="#e5a94b"><title>TI4 ${x.toFixed(2)} K · FRP ${y.toFixed(2)} MW · ${esc(points[i].observed_at_utc)}</title></circle>`}).join('')}</svg><div class="chart-point-detail" role="status" aria-live="polite">Hover over, focus, or select a point to inspect its archived values.</div>`;attachChartInspector(host,'.chart-point',points,x=>`${x.observed_at_utc} UTC · ${x.product} · ${x.satellite||'sensor unavailable'} · ${Number(x.latitude).toFixed(5)}, ${Number(x.longitude).toFixed(5)} · brightness ${Number(x.bright_ti4_k).toFixed(2)} K · FRP ${Number(x.frp_mw).toFixed(2)} MW · confidence ${x.confidence||'unavailable'} · source record ${x.raw_sha256||'not provided'}.`)}
function bindSpaceTimeView(){const form=$('#space-query'),table=$('#space-table'),status=$('#space-query-status');let offset=0,latest=null,requestId=0;loadPreventionCards($('#space-guidance'));const buildQuery=()=>{const p=new URLSearchParams();for(const [k,id] of [['start_date','space-start'],['end_date','space-end'],['west','space-west'],['south','space-south'],['east','space-east'],['north','space-north']])p.set(k,$(`#${id}`).value);const product=$('#space-product').value;if(product)p.set('product',product);p.set('limit','200');p.set('offset',String(offset));p.set('bbox',[p.get('west'),p.get('south'),p.get('east'),p.get('north')].join(','));for(const k of ['west','south','east','north'])p.delete(k);return p};const load=async()=>{const current=++requestId;const isCurrent=()=>form.isConnected && current===requestId;latest=null;for(const id of ['space-prev','space-next','space-export'])$('#'+id).disabled=true;for(const id of ['space-time-chart','space-scatter-chart'])$('#'+id).replaceChildren();status.textContent='Querying the indexed UTC/spatial data…';table.innerHTML='<div class="empty">Loading observation page…</div>';try{const d=await request('/data/fire-observations?'+buildQuery());if(!isCurrent())return;latest=d;renderDailyChart(d.time_series);renderFRPScatter(d.items);table.innerHTML=d.items.length?`<table class="experiment-table"><thead><tr><th>Observed UTC</th><th>Latitude</th><th>Longitude</th><th>Product / sensor</th><th>Confidence</th><th>FRP (MW)</th><th>Brightness TI4 (K)</th><th>Source object</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${esc(x.observed_at_utc)}</td><td>${Number(x.latitude).toFixed(5)}</td><td>${Number(x.longitude).toFixed(5)}</td><td>${esc(x.product)}<br><span class="small">${esc(x.satellite||'—')} / ${esc(x.instrument||'—')}</span></td><td>${esc(x.confidence||'—')}</td><td>${x.frp_mw===null?'—':Number(x.frp_mw).toFixed(2)}</td><td>${x.bright_ti4_k===null?'—':Number(x.bright_ti4_k).toFixed(2)}</td><td><a href="/api/data/raw-assets/${encodeURIComponent(x.raw_sha256)}/download">Raw CSV ↗</a></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No archived records match these filters. Download data in Earth Fire Observatory first.</div>';$('#space-page-count').textContent=`${d.total.toLocaleString()} matching records · rows ${d.total?offset+1:0}–${Math.min(offset+d.items.length,d.total)} · page size ${d.limit}`;$('#space-prev').disabled=offset===0;$('#space-next').disabled=offset+d.limit>=d.total;$('#space-export').disabled=!d.items.length;status.textContent=`UTC · EPSG:4326 · ${d.units.frp_mw} · stored FIRMS observations only. ${d.limitations}`}catch(e){if(!isCurrent())return;status.textContent=`Query failed: ${e.message}`;table.innerHTML='<div class="empty">Check the dates and keep the selected bounding box at or below 100 square degrees.</div>';$('#space-prev').disabled=true;$('#space-next').disabled=true;$('#space-export').disabled=true;$('#space-page-count').textContent='No query result.'}};form.addEventListener('submit',e=>{e.preventDefault();offset=0;load()});$('#space-prev').addEventListener('click',()=>{offset=Math.max(0,offset-200);load()});$('#space-next').addEventListener('click',()=>{offset+=200;load()});$('#space-export').addEventListener('click',()=>{if(!latest?.items.length)return;const cols=['observed_at_utc','latitude','longitude','product','satellite','instrument','confidence','frp_mw','bright_ti4_k','bright_ti5_k','raw_sha256'];const csv=[cols.join(','),...latest.items.map(x=>cols.map(k=>{const v=x[k]??'';return `"${safeSpreadsheetCell(v).replaceAll('"','""')}"`}).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='mors-spacetime-observations.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});load()}
